UPDATE "Service" SET "userInputForm"='[{"id":"generation_mode","type":"select","label":"Режим создания","required":true,"defaultValue":"prompt","hint":"По промпту — Seedance 2.0 создаёт сцену из текста. По фото — Kling 3.0 оживляет загруженный кадр фильма.","options":[{"value":"prompt","label":"По промпту"},{"value":"photo","label":"По фото"}]},{"id":"person1","type":"photo","label":"Ваше фото (необязательно)","required":false,"hint":"Если добавить фото, нейросеть будет сохранять вашу внешность. Без фото будет создана новая сцена без вашего референса.","allowStudioAvatars":true,"allowSystemLibrary":false},{"id":"scene_photo","type":"photo","label":"Кадр фильма","required":false,"requiredWhen":{"field":"generation_mode","value":"photo"},"visibleWhen":{"field":"generation_mode","value":"photo"},"mediaGroup":"scene","hint":"Загрузите кадр фильма или кинематографичную сцену. Kling 3.0 оживит этот кадр.","maxSizeMb":10,"allowedFormats":["jpg","jpeg","png","webp"],"allowStudioAvatars":false,"allowSystemLibrary":false},{"id":"prompt","type":"textarea","label":"Что должно произойти в сцене","required":false,"requiredWhen":{"field":"generation_mode","value":"prompt"},"maxLength":600,"placeholder":"Например: герой входит в неоновый город ночью, камера медленно приближается, дождь отражается в асфальте","hint":"В режиме «По промпту» описание обязательно. В режиме «По фото» можно оставить пустым — модель сама мягко оживит кадр."},{"id":"duration","type":"duration","label":"Длительность видео","required":false,"hint":"Kling 3.0 и Seedance 2.0 поддерживают короткие ролики до 15 секунд.","durationOptions":[5,8,10,15],"defaultDuration":5},{"id":"aspect","type":"aspect_ratio","label":"Формат кадра","required":false,"aspectOptions":["auto","9:16","16:9","1:1"],"defaultAspect":"16:9"}]'::jsonb, "pipelineConfig"='[{"id":"step_1","blockSlug":"scene-transfer","input":"{{user.person1}}","params":{"model":"kling-3-omni","generation_mode":"{{user.generation_mode}}","photo_model":"kling-3-omni","prompt_model":"seedance-2-omni","prompt_text_model":"seedance-2","scene_mode":"photo","scene_image":"{{user.scene_photo}}","primary_photo":"{{user.person1}}","people_count":"auto","stylize_characters":false,"photo_base_prompt":"Kling 3.0 Omni cinematic photo-to-video. Use the uploaded film still as the exact scene reference: preserve its location, era, composition, lens feeling, lighting, color palette, wardrobe logic, props and atmosphere. If a user photo is provided, integrate that person into the scene as a believable live-action character, not a pasted cutout.","prompt_base_prompt":"Seedance 2.0 cinematic text-to-video. Create a photorealistic live-action film scene from the user prompt with professional movie camera language: coherent story action, natural blocking, realistic physics, filmic lighting, controlled depth of field, high production value, stable faces and clean motion.","character_prompt":"When a user photo is provided, preserve identity with high priority: same face structure, eyes, eyebrows, nose, mouth, hairstyle, hair color, skin tone, age impression and natural facial character. Match perspective, scale, shadows and lighting to the scene. Do not beautify, de-age, change gender, duplicate, morph or replace the person.","no_reference_prompt":"No user photo was provided. Generate the movie scene directly from the prompt/reference frame without preserving any specific real-person identity.","user_prompt":"{{user.prompt}}","default_photo_prompt":"Animate the uploaded film frame with subtle believable movement: gentle camera motion, natural environmental motion, realistic depth and atmosphere. Keep the scene coherent and cinematic.","default_prompt_prompt":"Create a coherent cinematic scene with clear action, realistic camera movement and polished film lighting.","duration":"{{user.duration}}","aspect_ratio":"{{user.aspect}}","resolution":"720p"}}]'::jsonb, "shortDesc"='Создайте киносцену по промпту или оживите загруженный кадр фильма', "description"='Выберите режим: «По промпту» — опишите киносцену, и Seedance 2.0 создаст ролик; фото пользователя можно добавить как референс внешности, но это необязательно. «По фото» — загрузите кадр фильма или кинематографичную сцену, и Kling 3.0 оживит её; при наличии вашего фото нейросеть аккуратно поместит вас в кадр. Если фото пользователя не добавлено, сервис создаст сцену без сохранения вашей внешности.' WHERE slug='me-in-movie';
UPDATE "Service" SET "userInputForm"='[{"id":"generation_mode","type":"select","label":"Режим создания","required":true,"defaultValue":"prompt","hint":"По промпту — Seedance 2.0 создаёт мультсцену из текста. По фото — Kling 3.0 оживляет загруженный кадр мультфильма.","options":[{"value":"prompt","label":"По промпту"},{"value":"photo","label":"По фото"}]},{"id":"person1","type":"photo","label":"Ваше фото (необязательно)","required":false,"hint":"Если добавить фото, нейросеть сохранит вашу внешность. Без фото будет создана новая мультсцена без вашего референса.","allowStudioAvatars":true,"allowSystemLibrary":false},{"id":"cartoon_visual_mode","type":"select","label":"Визуал персонажа","required":true,"defaultValue":"realistic","hint":"Реалистичный — человек остаётся как живой внутри мультмира. Мультяшный — фото превращается в мультперсонажа.","options":[{"value":"realistic","label":"Реалистичный"},{"value":"cartoon","label":"Мультяшный"}]},{"id":"cartoon_style","type":"select","label":"Стиль мультфильма","required":true,"defaultValue":"classic hand-drawn fairy-tale animation: warm color palette, clean expressive linework, soft painterly backgrounds, family adventure mood, elegant character acting","options":[{"value":"classic hand-drawn fairy-tale animation: warm color palette, clean expressive linework, soft painterly backgrounds, family adventure mood, elegant character acting","label":"Классический 2D"},{"value":"modern 3D animated feature style: rounded appealing shapes, polished materials, cinematic lighting, colorful detailed environments, expressive but controlled animation","label":"Современный 3D"},{"value":"anime-inspired cinematic animation: clean cel shading, expressive eyes, dynamic camera angles, detailed backgrounds, dramatic lighting, emotional movement","label":"Аниме"},{"value":"comic-book animation style: bold outlines, graphic shadows, energetic poses, saturated color blocks, stylized motion and cinematic panel composition","label":"Комикс"},{"value":"soft clay stop-motion inspired animation: tactile handmade textures, rounded forms, cozy lighting, gentle whimsical movement, miniature set feeling","label":"Пластилиновый"}]},{"id":"scene_photo","type":"photo","label":"Фото-кадр мультфильма","required":false,"requiredWhen":{"field":"generation_mode","value":"photo"},"visibleWhen":{"field":"generation_mode","value":"photo"},"mediaGroup":"scene","hint":"Загрузите кадр мультфильма. Kling 3.0 оживит его и, если есть ваше фото, перенесёт персонажа в этот мультмир.","maxSizeMb":10,"allowedFormats":["jpg","jpeg","png","webp"],"allowStudioAvatars":false,"allowSystemLibrary":false},{"id":"prompt","type":"textarea","label":"Что должно произойти в сцене","required":false,"requiredWhen":{"field":"generation_mode","value":"prompt"},"maxLength":600,"placeholder":"Например: герой летит над сказочным городом на светящемся зонте, камера плавно облетает башни","hint":"В режиме «По промпту» описание обязательно. В режиме «По фото» можно оставить пустым — модель сама мягко оживит кадр."},{"id":"duration","type":"duration","label":"Длительность видео","required":false,"hint":"Kling 3.0 и Seedance 2.0 поддерживают короткие ролики до 15 секунд.","durationOptions":[5,8,10,15],"defaultDuration":5},{"id":"aspect","type":"aspect_ratio","label":"Формат кадра","required":false,"aspectOptions":["auto","9:16","16:9","1:1"],"defaultAspect":"9:16"}]'::jsonb, "pipelineConfig"='[{"id":"step_1","blockSlug":"scene-transfer","input":"{{user.person1}}","params":{"model":"kling-3-omni","generation_mode":"{{user.generation_mode}}","photo_model":"kling-3-omni","prompt_model":"seedance-2-omni","prompt_text_model":"seedance-2","scene_mode":"photo","scene_image":"{{user.scene_photo}}","primary_photo":"{{user.person1}}","people_count":"auto","stylize_characters":false,"stylize_model":"nano-banana","stylize_prompt":"Create a polished animated character from the uploaded person reference while preserving recognizable identity: same face structure, eye shape, nose, mouth, hairstyle, age impression and personality. Match this selected animation direction: {{user.cartoon_style}}. Clean production-quality character design, stable face, expressive but not exaggerated, no text, no watermark, no extra people.","photo_base_prompt":"Kling 3.0 Omni cartoon photo-to-video. Use the uploaded cartoon still as the exact scene reference: preserve its composition, world, colors, props, camera framing and animation atmosphere. If a user photo is provided, integrate the referenced person into the cartoon scene according to the selected visual mode.","prompt_base_prompt":"Seedance 2.0 animated text-to-video. Create a coherent high-quality cartoon scene from the user prompt with clear staging, appealing animation design, stable characters, expressive motion, polished lighting and a family-friendly adventure feeling.","character_prompt":"If a user photo is provided, preserve the person identity according to the selected visual mode. Keep the face stable and recognizable across frames. Do not blend the person with background characters, do not duplicate them, do not add extra copies, and do not distort eyes, mouth or hands.","no_reference_prompt":"No user photo was provided. Generate the cartoon scene directly from the prompt/reference frame without preserving any specific real-person identity.","cartoon_visual_mode":"{{user.cartoon_visual_mode}}","cartoon_style":"{{user.cartoon_style}}","cartoon_realistic_prompt":"Realistic visual mode: if a user photo is provided, keep the referenced person photorealistic and instantly recognizable inside the animated world. Preserve real human skin texture, natural face proportions, realistic eyes and hair, correct scale, contact shadows and scene-matched lighting. The world is animated, but the referenced person should look like a real person genuinely filmed inside it, not a sticker and not a cartoon.","cartoon_character_prompt":"Cartoon visual mode: if a user photo is provided, transform the referenced person into a polished animated character while preserving identity. Keep the same face structure, eye shape, nose, mouth, hairstyle, age impression and personality, but render them in the selected cartoon style with clean shapes, stable face, appealing design and natural animation.","cartoon_style_prompt":"Apply the selected cartoon style consistently to the environment, color palette, character design, lighting and motion. Avoid copyrighted logos, text, watermarks, malformed faces, flicker and random extra characters.","user_prompt":"{{user.prompt}}","default_photo_prompt":"Animate the uploaded cartoon frame with charming natural motion: gentle camera movement, lively background details, expressive but stable character motion and coherent scene physics.","default_prompt_prompt":"Create a charming animated scene with clear action, appealing characters, polished motion and a coherent cartoon world.","duration":"{{user.duration}}","aspect_ratio":"{{user.aspect}}","resolution":"720p"}}]'::jsonb, "shortDesc"='Создайте мультсцену по промпту или оживите загруженный кадр мультфильма', "description"='Выберите режим: «По промпту» — опишите мультсцену, и Seedance 2.0 создаст ролик; ваше фото можно добавить как референс внешности, но это необязательно. «По фото» — загрузите кадр мультфильма, и Kling 3.0 оживит его; при наличии вашего фото нейросеть перенесёт вас в мультмир. Можно выбрать визуал персонажа: реалистичный человек в мультфильме или полностью мультяшный персонаж, а также стиль мультфильма.' WHERE slug='me-in-cartoon';
